core:
function score(clicks, seconds){ clicks=+clicks; seconds=+seconds; if(!(seconds>0)) return {error:'时长须为正'};
  return {cps:Math.round(clicks/seconds*100)/100, clicks:clicks, seconds:seconds}; }
function grade(cps){ cps=+cps; return cps>=8?'极快': cps>=6?'快': cps>=4?'中等': cps>=2?'慢':'新手'; }
var EXPORTS={score:score, grade:grade};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CpsForgePure = EXPORTS; }
